    actual={p.relative_to(ROOT).as_posix() for p in (ROOT/'updates/EW/package').rglob('*') if p.is_file()};need(actual==set(PINS),'extra/missing public disclosure')
    pkg=m['recovered_packages'][0];prefix='astra_frontier_separable_completion/'
